// Приводим ответ WB к общему виду панели.
// Поля соответствуют OpenAPI-спецификации communications: ResponseFeedbackInner.
const response = $input.first()?.json ?? {};

if (response.error) {
  return [{ json: { __empty: true, __error: String(response.errorText ?? response.message ?? 'WB вернул ошибку') } }];
}

const feedbacks = response?.data?.feedbacks ?? [];
if (feedbacks.length === 0) {
  return [{ json: { __empty: true, __error: null } }];
}

return feedbacks.map((feedback) => {
  const product = feedback.productDetails ?? {};
  const review = {
    __empty: false,
    externalId: String(feedback.id),
    rating: feedback.productValuation ?? null,
    text: feedback.text || null,
    pros: feedback.pros || null,
    cons: feedback.cons || null,
    authorName: feedback.userName || null,
    productName: product.productName ?? null,
    productSku: product.nmId ? String(product.nmId) : null,
    productBrand: product.brandName ?? null,
    productArticle: product.supplierArticle ?? null,
    photos: (feedback.photoLinks ?? []).map((photo) => photo.fullSize || photo.miniSize).filter(Boolean),
    mpCreatedAt: feedback.createdDate ?? null,
    raw: feedback,
  };

  const parts = [
    `Товар: ${review.productName ?? 'не указан'}`,
    `Оценка: ${review.rating ?? 'нет'} из 5`,
    review.text ? `Отзыв: ${review.text}` : null,
    review.pros ? `Достоинства: ${review.pros}` : null,
    review.cons ? `Недостатки: ${review.cons}` : null,
    review.authorName ? `Имя покупателя: ${review.authorName}` : null,
  ].filter(Boolean);

  return { json: { ...review, aiUserPrompt: parts.join('\n') } };
});

// Склеиваем отзывы с ответами модели по порядку следования элементов.
const reviewsIn = $('WB: нормализация').all();
const drafts = $input.all();

const reviews = reviewsIn.map((item, index) => {
  const { __empty, aiUserPrompt, ...review } = item.json;
  const answer = drafts[index]?.json ?? {};
  const content = answer?.choices?.[0]?.message?.content;

  return {
    ...review,
    aiDraft: typeof content === 'string' && content.trim() ? content.trim() : null,
    aiModel: answer?.model ?? null,
  };
});

return [{ json: { marketplace: 'wb', reviews, syncError: null } }];

// Приводим ответ Ozon к общему виду панели (схема ReviewAPI_ReviewList).
const response = $input.first()?.json ?? {};

if (response.code || response.message) {
  return [{ json: { __empty: true, __error: String(response.message ?? 'Ozon вернул ошибку') } }];
}

const reviews = response.reviews ?? [];
if (reviews.length === 0) {
  return [{ json: { __empty: true, __error: null } }];
}

return reviews.map((review) => {
  const normalized = {
    __empty: false,
    externalId: String(review.id),
    rating: review.rating ?? null,
    text: review.text || null,
    pros: null,
    cons: null,
    authorName: null,
    productName: null,
    productSku: review.sku ? String(review.sku) : null,
    productBrand: null,
    productArticle: null,
    photos: [],
    mpCreatedAt: review.published_at ?? null,
    raw: review,
  };

  const parts = [
    `Товар: SKU ${normalized.productSku ?? 'не указан'}`,
    `Оценка: ${normalized.rating ?? 'нет'} из 5`,
    normalized.text ? `Отзыв: ${normalized.text}` : null,
  ].filter(Boolean);

  return { json: { ...normalized, aiUserPrompt: parts.join('\n') } };
});

const reviewsIn = $('Ozon: нормализация').all();
const drafts = $input.all();

const reviews = reviewsIn.map((item, index) => {
  const { __empty, aiUserPrompt, ...review } = item.json;
  const answer = drafts[index]?.json ?? {};
  const content = answer?.choices?.[0]?.message?.content;

  return {
    ...review,
    aiDraft: typeof content === 'string' && content.trim() ? content.trim() : null,
    aiModel: answer?.model ?? null,
  };
});

return [{ json: { marketplace: 'ozon', reviews, syncError: null } }];
